                <script type="text/javascript">
                    function news() {
                        var url = prompt("Поделиться интересной новостью с сайтов:\n onliner.by, iguides.ru, habrahabr.ru, gameland.ru, allgamenews.net", "http://");
                        if (!url) return false;
                        ajax.news(url);
